'use strict';
const C=StudioCore,$=id=>document.getElementById(id),KEY='meme-card-studio-v1';
let state={...C.defaults},image=null,templates=[],selected=null,revision=0,busy=false;
const presets=[{...C.defaults},{...C.defaults,text:'천천히 가도\n괜찮아.',ratio:'4:5',bg:'#cbdcff',color:'#253e7d',font:'serif'},{...C.defaults,text:'작은 시작,\n꽤 큰 가능성.',ratio:'9:16',bg:'#f2d1dc',color:'#73384f',size:100}];
function message(s,error=false){$('status').textContent=s;$('status').className=error?'error':'';}
function draw(){const l=C.render($('canvas'),state,image);$('dimensions').textContent=C.sizes[state.ratio].join(' × ')+' px';$('layoutNote').textContent=l.reduced?'긴 문구가 잘리지 않도록 '+Math.round(l.size*10)/10+'px로 자동 맞춤했습니다.':'문구가 가장자리를 넘으면 안쪽으로 맞춰요.';$('count').textContent=state.text.length+' / 2,000';for(const k of ['size','x','y'])$(k+'Out').textContent=state[k]+(k==='size'?' px':'%');document.querySelectorAll('[data-ratio]').forEach(b=>{b.classList.toggle('active',b.dataset.ratio===state.ratio);b.setAttribute('aria-pressed',String(b.dataset.ratio===state.ratio));});}
function sync(){for(const k of ['text','size','color','bg','x','y','font','align','fit'])$(k).value=state[k];for(const k of ['stroke','transparent'])$(k).checked=state[k];$('update').disabled=!selected;draw();}
function decode(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>i.width*i.height>40000000?reject(Error('이미지는 4천만 픽셀 이하여야 합니다.')):resolve(i);i.onerror=()=>reject(Error('손상된 이미지입니다. 기존 작업은 유지됩니다.'));i.src=src;});}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('파일을 읽지 못했습니다.'));r.readAsDataURL(file);});}
async function upload(file){if(!file)return;const token=++revision;try{if(!['image/png','image/jpeg'].includes(file.type))throw Error('PNG 또는 JPEG 파일만 사용할 수 있습니다. 기존 작업은 유지됩니다.');if(file.size>10*1024*1024)throw Error('10MB 이하의 이미지를 선택해주세요.');const raw=await fileData(file),img=await decode(raw);const c=document.createElement('canvas'),f=Math.min(1,1600/Math.max(img.width,img.height));c.width=Math.round(img.width*f);c.height=Math.round(img.height*f);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const safe=c.toDataURL(file.type,file.type==='image/jpeg'?.9:undefined);if(safe.length>4000000)throw Error('저장할 이미지가 너무 큽니다. 더 작은 이미지를 선택해주세요.');const ready=await decode(safe);if(token!==revision)return;image=ready;state={...state,image:safe};draw();message('이미지를 불러왔어요. 원본 메타데이터는 제외했습니다.');}catch(e){if(token===revision)message(e.message,true);}finally{$('imageFile').value='';}}
for(const k of ['text','size','color','bg','x','y','font','align','fit','stroke','transparent'])$(k).addEventListener('input',()=>{state[k]=['stroke','transparent'].includes(k)?$(k).checked:['size','x','y'].includes(k)?Number($(k).value):$(k).value;draw();});
$('imageFile').onchange=e=>upload(e.target.files[0]);$('drop').ondragover=e=>{e.preventDefault();};$('drop').ondrop=e=>{e.preventDefault();upload(e.dataTransfer.files[0]);};
$('removeImage').onclick=()=>{revision++;image=null;state.image=null;draw();message('이미지를 지웠어요. 문구와 설정은 유지됩니다.');};
document.querySelectorAll('[data-ratio]').forEach(b=>b.onclick=()=>{state.ratio=b.dataset.ratio;draw();});
$('reset').onclick=()=>{if(!confirm('현재 편집 내용을 초기화할까요? 저장한 템플릿은 유지됩니다.'))return;revision++;state={...C.defaults};image=null;selected=null;$('name').value='';sync();list();message('새 카드로 시작합니다.');};
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{revision++;state={...presets[Number(b.dataset.preset)]};image=null;selected=null;$('name').value='';sync();list();message('시작 문구를 불러왔어요. 자유롭게 바꿔보세요.');});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('exportTop').onclick=async()=>{await document.fonts.ready;draw();$('canvas').toBlob(blob=>{if(!blob){message('이미지 저장에 실패했어요.',true);return;}download(blob,'my-card-'+state.ratio.replace(':','x')+'.png');message('PNG를 저장했어요. 미리보기와 같은 캔버스를 사용합니다.');},'image/png');};
function persist(next){try{localStorage.setItem(KEY,JSON.stringify({version:1,templates:next}));templates=next;return true;}catch(e){message('저장 공간이 부족하거나 브라우저 저장이 차단됐어요. 기존 템플릿은 유지됩니다. JSON을 백업한 뒤 이미지를 줄여주세요.',true);return false;}}
function save(update){const name=$('name').value.trim();if(!name){message('템플릿 이름을 적어주세요.',true);$('name').focus();return;}if(!update&&templates.length>=50){message('템플릿은 최대 50개까지 저장할 수 있어요.',true);return;}const entry={id:update?selected:crypto.randomUUID(),name,state:structuredClone(state)};const next=update?templates.map(t=>t.id===selected?entry:t):[...templates,entry];if(persist(next)){selected=entry.id;$('update').disabled=false;list();message(update?'선택한 템플릿을 수정했어요.':'새 템플릿을 저장했어요.');}}
$('save').onclick=()=>save(false);$('update').onclick=()=>save(true);
async function loadTemplate(t){const token=++revision;try{const ready=t.state.image?await decode(t.state.image):null;if(token!==revision)return;state=structuredClone(t.state);image=ready;selected=t.id;$('name').value=t.name;sync();list();message('“'+t.name+'”을 불러왔어요. 변경 후 ‘선택한 항목 수정’을 누르면 저장됩니다.');}catch(e){message(e.message,true);}}
async function list(){const generation=++list.generation;const target=$('templateList');target.replaceChildren();$('total').textContent=templates.length;if(!templates.length){const e=document.createElement('div');e.className='empty';e.textContent='아직 저장한 템플릿이 없어요. 첫 조합을 보관해보세요.';target.append(e);return;}for(const t of templates){const card=document.createElement('article');card.className='template-card'+(t.id===selected?' selected':'');const thumb=document.createElement('button');thumb.className='thumb';thumb.setAttribute('aria-label',t.name+' 불러오기');thumb.onclick=()=>loadTemplate(t);const title=document.createElement('div');title.className='title';title.textContent=t.name;const actions=document.createElement('div');actions.className='row';const load=document.createElement('button');load.textContent='불러오기';load.onclick=()=>loadTemplate(t);const del=document.createElement('button');del.textContent='삭제';del.onclick=()=>{if(confirm('“'+t.name+'” 템플릿을 삭제할까요?')&&persist(templates.filter(x=>x.id!==t.id))){if(selected===t.id){selected=null;$('update').disabled=true;}list();message('템플릿을 삭제했어요.');}};actions.append(load,del);card.append(thumb,title,actions);target.append(card);try{const img=t.state.image?await decode(t.state.image):null;if(generation!==list.generation)return;const c=document.createElement('canvas');C.render(c,t.state,img);const small=document.createElement('canvas');small.width=180;small.height=Math.round(180*c.height/c.width);small.getContext('2d').drawImage(c,0,0,small.width,small.height);const preview=document.createElement('img');preview.alt=t.name;preview.src=small.toDataURL();thumb.append(preview);}catch{thumb.textContent='미리보기 없음';}}}list.generation=0;
$('backup').onclick=()=>{download(new Blob([JSON.stringify({version:1,templates},null,2)],{type:'application/json'}),'card-templates.json');message(templates.length+'개 템플릿을 백업했어요. 이미지와 편집 설정이 함께 들어 있습니다.');};
$('jsonFile').onchange=async e=>{const f=e.target.files[0];if(!f||busy)return;busy=true;try{if(f.size>20000000)throw Error('JSON은 20MB 이하여야 합니다.');let obj;try{obj=JSON.parse(await f.text());}catch{throw Error('JSON 문법이 손상됐습니다. 기존 템플릿은 유지됩니다.');}const incoming=C.validateBackup(obj);for(const t of incoming)if(t.state.image)await decode(t.state.image);const ids=new Set(templates.map(t=>t.id));const merged=[...templates,...incoming.map(t=>({...t,id:ids.has(t.id)?crypto.randomUUID():t.id}))];if(merged.length>50)throw Error('합친 템플릿이 50개를 넘어요. 일부를 삭제한 뒤 다시 가져와주세요.');if(persist(merged)){list();message(incoming.length+'개 템플릿을 가져왔어요. 기존 템플릿도 유지됩니다.');}}catch(err){message(err.message,true);}finally{busy=false;e.target.value='';}};
try{const raw=localStorage.getItem(KEY);if(raw)templates=C.validateBackup(JSON.parse(raw));}catch{message('저장된 데이터를 읽지 못했어요. 원본 저장값은 변경하지 않았습니다. JSON 백업으로 복원해주세요.',true);}
sync();document.fonts.ready.then(()=>{draw();list();});
if(document.modelContext?.registerTool){const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'set_card_text',description:'현재 카드의 문구를 변경하고 미리보기에 반영합니다. 저장이나 다운로드는 하지 않습니다.',inputSchema:{type:'object',properties:{text:{type:'string',maxLength:2000}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.text!=='string'||input.text.length>2000)throw Error('문구는 2000자 이하 문자열이어야 합니다.');state.text=input.text;sync();return {text:state.text,ratio:state.ratio};}},{signal:controller.signal})).catch(()=>{});}catch{}addEventListener('pagehide',()=>controller.abort(),{once:true});}
